local home = os.getenv("HOME")
local wal = dofile(home .. "/.cache/wal/colors-hyprland.lua")

--###############
--## MONITORS ###
--###############
hl.window_rule({
    name = "kitty-no-maximize",
    match = {
        class = "kitty",
    },
    suppress_event = "maximize",
})

-- See https://wiki.hyprland.org/Configuring/Monitors/

hl.monitor({
    output = "DP-4",
    mode = "2048x1152",
    position = "auto-left",
    scale = "1",
})

hl.monitor({
    output = "eDP-1",
    mode = "2256x1504",
    position = "auto",
    scale = "1",
})

--monitor=eDP-1,2256x1504,auto,1
--monitor=DP-4,2560x1440,auto-up,1

--monitor=DP-4,2560x1440,auto,1,mirror,eDP-1
